import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { UserData, GradeStatus } from '../types';
import { supabase } from '../utils/supabase';
import { 
    calculateCumulativeStats, 
    calculateSemesterStats, 
    calculateSubjectAverage, 
    getGradeDetails,
    getDegreeClassification,
    getSubjectStatus
} from './calculations';

// Hàm helper để convert file font sang base64 an toàn
const arrayBufferToBase64 = (buffer: ArrayBuffer) => {
    let binary = '';
    const bytes = new Uint8Array(buffer);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return window.btoa(binary);
};

export const exportTranscriptToPdf = async (data: UserData) => {
    const doc = new jsPDF();
    const MARGIN_LEFT = 15; // Ép chuẩn lề trái 15px cho toàn bộ văn bản
    const PAGE_WIDTH = 210;
    const MARGIN_RIGHT = PAGE_WIDTH - MARGIN_LEFT; // Lề phải chuẩn

    // 1. TẢI FONT CHUẨN TIMES NEW ROMAN 
    try {
        const fontBaseUrl = 'https://cdn.jsdelivr.net/gh/google/fonts@main/apache/tinos';
        
        const [regRes, boldRes, italicRes] = await Promise.all([
            fetch(`${fontBaseUrl}/Tinos-Regular.ttf`),
            fetch(`${fontBaseUrl}/Tinos-Bold.ttf`),
            fetch(`${fontBaseUrl}/Tinos-Italic.ttf`)
        ]);

        const [regBuf, boldBuf, italicBuf] = await Promise.all([
            regRes.arrayBuffer(),
            boldRes.arrayBuffer(),
            italicRes.arrayBuffer()
        ]);

        doc.addFileToVFS('Tinos-Regular.ttf', arrayBufferToBase64(regBuf));
        doc.addFileToVFS('Tinos-Bold.ttf', arrayBufferToBase64(boldBuf));
        doc.addFileToVFS('Tinos-Italic.ttf', arrayBufferToBase64(italicBuf));

        doc.addFont('Tinos-Regular.ttf', 'Tinos', 'normal');
        doc.addFont('Tinos-Bold.ttf', 'Tinos', 'bold');
        doc.addFont('Tinos-Italic.ttf', 'Tinos', 'italic');
        
        doc.setFont('Tinos', 'normal'); 
    } catch (error) {
        console.error("Lỗi tải font tiếng Việt:", error);
    }

    // LẤY MSSV TỰ ĐỘNG
    let studentCode = (data as any).studentCode || (data as any).student_code;
    if (!studentCode) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (user) {
                const { data: profile } = await supabase.from('profiles').select('student_code').eq('id', user.id).single();
                if (profile?.student_code) studentCode = profile.student_code;
            }
        } catch (err) {
            console.log("Không thể fetch MSSV dự phòng", err);
        }
    }
    studentCode = studentCode || '.....................';

    const studentName = data.studentName || '................................';
    const programName = data.programName || 'Đại học chính quy chuẩn';
    const cohort = data.cohort || '.......';
    const majorName = data.majorName || '................................';
    const specName = data.specializationName || '................................';

    // --- HEADER: QUỐC HIỆU & TIÊU NGỮ ---
    doc.setFontSize(12); // TOÀN BỘ CHỮ SIZE 12
    doc.setTextColor(0, 0, 0); 
    
    // Cột trái
    doc.setFont('Tinos', 'bold');
    doc.text("HUB PLANNER", 50, 20, { align: "center" });
    doc.text("HỆ THỐNG HỖ TRỢ SINH VIÊN", 50, 26, { align: "center" });
    doc.setLineWidth(0.5);
    doc.line(30, 28, 70, 28); 

    // Cột phải
    doc.text("CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM", 155, 20, { align: "center" });
    doc.text("Độc lập - Tự do - Hạnh phúc", 155, 26, { align: "center" });
    doc.line(125, 28, 185, 28); 

    const today = new Date();
    doc.setFont('Tinos', 'italic');
    doc.text(`TP. Hồ Chí Minh, ngày ${today.getDate().toString().padStart(2, '0')} tháng ${(today.getMonth() + 1).toString().padStart(2, '0')} năm ${today.getFullYear()}`, 155, 34, { align: "center" });

    // --- TIÊU ĐỀ (Duy nhất chỗ này size 16) ---
    doc.setFont('Tinos', 'bold');
    doc.setFontSize(16); 
    doc.text("GIẤY CHỨNG NHẬN KẾT QUẢ HỌC TẬP", 105, 50, { align: "center" });

    // --- THÔNG TIN SINH VIÊN ---
    doc.setFont('Tinos', 'normal');
    doc.setFontSize(12); // TRỞ VỀ LẠI SIZE 12
    const startY = 62;
    const gapY = 6; // Dãn dòng khít lại
    const col1X = MARGIN_LEFT; // Canh đúng lề 15
    const col2X = 110;

    doc.text(`Họ và tên SV: ${studentName}`, col1X, startY);
    doc.text(`Khóa: ${cohort}`, col2X, startY);

    doc.text(`Mã số SV: ${studentCode}`, col1X, startY + gapY);
    doc.text(`Ngành đào tạo: ${majorName}`, col2X, startY + gapY);

    doc.text(`Hình thức đào tạo: Chính quy`, col1X, startY + gapY * 2);
    doc.text(`Chuyên ngành: ${specName}`, col2X, startY + gapY * 2); 

    const validDataSemesters = data.semesters.filter(s => /^Học kỳ (1|2|3|Hè) Năm học \d{4}-\d{4}$/.test(s.name));

    // --- BẢNG ĐIỂM ---
    let currentY = startY + gapY * 2 + 10;

    validDataSemesters.forEach((sem) => {
        const semStats = calculateSemesterStats(sem.subjects);
        if (!semStats.hasData && sem.subjects.length === 0) return; 

        doc.setFont('Tinos', 'bold');
        doc.setFontSize(12);
        doc.text(sem.name, MARGIN_LEFT, currentY); // Canh đúng lề 15
        
        doc.setFont('Tinos', 'normal');
        doc.text(`GPA(4): ${semStats.gpa4.toFixed(2)}  |  GPA(10): ${semStats.gpa10.toFixed(2)}  |  ĐRL: ${sem.trainingScore ?? '-'}`, MARGIN_RIGHT, currentY, { align: 'right' }); // Canh đúng lề phải 195

        const tableBody = sem.subjects.map((sub, index) => {
            const avg10 = calculateSubjectAverage(sub);
            const { scale4, letter } = avg10 !== null ? getGradeDetails(avg10) : { scale4: null, letter: '-' };
            const status = avg10 !== null ? (getSubjectStatus(avg10) === GradeStatus.FAIL ? 'Rớt' : 'Đậu') : '-';
            
            return [
                index + 1,
                sub.name + (sub.isNonGPA ? ' (*)' : ''),
                sub.credits,
                avg10 !== null ? avg10.toFixed(1) : '-',
                scale4 !== null ? scale4.toFixed(1) : '-',
                letter,
                status
            ];
        });

        autoTable(doc, {
            startY: currentY + 3,
            margin: { left: MARGIN_LEFT, right: MARGIN_LEFT }, // Ép bảng canh đúng lề 15 giống chữ
            head: [['STT', 'Tên học phần', 'Số tín chỉ', 'Thang 10', 'Thang 4', 'Điểm chữ', 'Kết quả']],
            body: tableBody,
            theme: 'grid',
            styles: { 
                font: 'Tinos', 
                fontSize: 12, // BẢNG CŨNG SIZE 12
                cellPadding: 2,
                textColor: 0,
                lineColor: 0,
                lineWidth: 0.1
            },
            headStyles: { 
                font: 'Tinos',
                fontStyle: 'bold',
                fillColor: [240, 240, 240],
                textColor: 0,
                halign: 'center'
            },
            columnStyles: {
                0: { halign: 'center', cellWidth: 12 },
                1: { cellWidth: 'auto' },
                2: { halign: 'center', cellWidth: 23 },
                3: { halign: 'center', cellWidth: 18 },
                4: { halign: 'center', cellWidth: 18 },
                5: { halign: 'center', cellWidth: 19 },
                6: { halign: 'center', cellWidth: 18 },
            },
            didDrawPage: (data) => {
                const pageSize = doc.internal.pageSize;
                const pageHeight = pageSize.height ? pageSize.height : pageSize.getHeight();
                doc.setFontSize(12);
                doc.setFont('Tinos', 'normal');
                doc.text(`Trang ${doc.getNumberOfPages()}`, MARGIN_RIGHT, pageHeight - 10, { align: 'right' });
            }
        });

        currentY = (doc as any).lastAutoTable.finalY + 12;
    });

    if (currentY > 230) {
        doc.addPage();
        currentY = 20;
    }

    // --- TỔNG KẾT TÍCH LŨY ---
    const stats = calculateCumulativeStats(validDataSemesters);
    const classification = getDegreeClassification(stats.gpa4);

    doc.setFont('Tinos', 'normal');
    doc.setFontSize(12); // SIZE 12 CHUẨN MỰC
    
   // Cột trái: Điểm trung bình các hệ
    doc.text(`Điểm trung bình (hệ 4): ${stats.gpa4.toFixed(2)}`, MARGIN_LEFT, currentY);
    doc.text(`Điểm trung bình (hệ 10): ${stats.gpa10.toFixed(2)}`, MARGIN_LEFT, currentY + gapY);
    
    // Cột phải: Tín chỉ và Xếp loại
    doc.text(`Số tín chỉ tích lũy: ${stats.passedCredits}/${data.totalCreditsRequired || 125}`, 110, currentY);
    doc.text(`Xếp loại học lực: ${classification}`, 110, currentY + gapY);

    doc.text('Ghi chú: (*) Môn học không tính vào điểm trung bình tích lũy.', MARGIN_LEFT, currentY + gapY * 2.5);

    // --- CHỮ KÝ ---
    doc.setFontSize(12);
    doc.setFont('Tinos', 'bold');
    
    const sigY = currentY + gapY * 5;
    
    doc.text("NGƯỜI SÁNG LẬP", 155, sigY, { align: "center" });
    doc.text("HỆ THỐNG HỖ TRỢ SINH VIÊN", 155, sigY + 5, { align: "center" });
    
    // 👇 SẾP CHÈN LẠI MÃ BASE64 MỘC ĐỎ VÀO BIẾN NÀY NHÉ 👇
    const stampBase64 = "data:image/png;base64,"; 
    doc.addImage(stampBase64, 'PNG', 110, sigY + 7, 40, 40, undefined, 'FAST', -15);

    doc.setFont('Tinos', 'normal');
    doc.text("Trần Quốc Hoàng", 155, sigY + 36, { align: "center" });

    const safeFileName = (studentName || 'Bang_Diem').replace(/ /g, '_').replace(/[^a-zA-Z0-9_]/g, '');
    doc.save(`${safeFileName}_Transcript.pdf`);
};